#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys
import time

import booster_robotics_sdk_python as br


AUDIO_SOURCE_MAP = {
    "pcm": br.AudioSourceType.kPcmFile,
    "wav": br.AudioSourceType.kWavFile,
    "mp3": br.AudioSourceType.kMp3File,
}

BT_PROFILE_MAP = {
    "none": br.BluetoothAudioProfile.kNone,
    "a2dp_sink": br.BluetoothAudioProfile.kA2dpSink,
    "a2dp_source": br.BluetoothAudioProfile.kA2dpSource,
    "hfp_headset": br.BluetoothAudioProfile.kHfpHeadset,
    "hfp_ag": br.BluetoothAudioProfile.kHfpAg,
}


def print_help():
    print(
        """
Available commands (Audio):
  help
  manager_init                   - Init AudioManager and recreate audio objects
  manager_info                   - Show manager init state and client id
  manager_request_id             - Generate and print an audio request id
  manager_shutdown               - Shutdown AudioManager resources

  player_init <pcm|wav|mp3> <path> [priority]
                                  - Init file player. priority: low|medium|high
  player_stream_init [sample_rate] [channels] [bits]
                                  - Init PCM stream player
  player_start
  player_pause
  player_stop
  player_reset
  player_destroy
  player_release
  player_info
  player_volume <0.0-1.0>
  player_push <pcm_path> [chunk_bytes] [sleep_ms]
                                  - Push PCM file bytes to stream player

  rec_init <output_path> [sample_rate] [channels] [bits]
  rec_start
  rec_pause
  rec_stop
  rec_destroy
  rec_release
  rec_info

  sys_volume [value]             - No arg: get volume. With arg: set volume
  sys_mute [on|off]              - No arg: get mute. With arg: set mute
  devices [inputs|outputs]       - List current input/output devices
  player_device <device_id>      - Set preferred output device for player
  rec_device <device_id>         - Set preferred input device for recorder
  cap_device <device_id>         - Set preferred input device for capture
  doa                            - Get DOA angle
  bt_scan [timeout_ms] [audio_only]
                                  - Start Bluetooth scan. audio_only: on|off
  bt_scan_stop                    - Stop Bluetooth scan
  bt_devices [include_unpaired]   - List Bluetooth devices
  bt_connect <address> [profile] [timeout_ms] [auto_pair] [make_default]
                                  - profile: none|a2dp_sink|a2dp_source|hfp_headset|hfp_ag
  bt_disconnect <address>
  bt_forget <address>

  cap_init [raw|naec|both] [sample_rate] [channels] [bits]
  cap_start
  cap_pause
  cap_stop
  cap_destroy
  cap_info

  quit / exit
"""
    )


def parse_player_priority(token: str):
    token = token.lower()
    if token == "low":
        return br.PlayerPriority.kLow
    if token == "medium":
        return br.PlayerPriority.kMedium
    if token == "high":
        return br.PlayerPriority.kHigh
    raise ValueError("priority must be one of: low, medium, high")


def parse_bt_profile(token: str):
    profile = BT_PROFILE_MAP.get(token.lower())
    if profile is None:
        raise ValueError(
            "profile must be one of: none, a2dp_sink, a2dp_source, "
            "hfp_headset, hfp_ag"
        )
    return profile


def parse_bool_token(token: str) -> bool:
    token = token.lower()
    if token in ("1", "true", "on", "yes"):
        return True
    if token in ("0", "false", "off", "no"):
        return False
    raise ValueError("boolean value must be one of: on/off, true/false, 1/0")


def print_manager_info(manager):
    print(
        "[manager]",
        f"initialized={manager.IsInitialized()}",
        f"client_id={manager.GetClientId()}",
    )


def print_player_info(info):
    print(
        "[player]",
        f"state={info.state}",
        f"played_bytes={info.played_bytes}",
        f"total_bytes={info.total_bytes}",
        f"volume={info.volume:.2f}",
    )


def print_player_status(player):
    print_player_info(player.GetInfo())
    print(
        "[player status]",
        f"session_id={player.GetSessionId()}",
        f"cached_state={player.GetCachedState()}",
    )


def print_recorder_info(info):
    print(
        "[recorder]",
        f"state={info.state}",
        f"captured_bytes={info.captured_bytes}",
    )


def print_recorder_status(recorder):
    print_recorder_info(recorder.GetInfo())
    print(
        "[recorder status]",
        f"session_id={recorder.GetSessionId()}",
        f"cached_state={recorder.GetCachedState()}",
    )


def print_capture_info(info):
    print(
        "[capture]",
        f"state={info.state}",
        f"raw_enabled={info.raw_enabled}",
        f"naec_enabled={info.naec_enabled}",
        f"published_frames={info.published_frames}",
        f"dropped_frames={info.dropped_frames}",
        f"raw_format={info.actual_raw_format.sample_rate_hz}/"
        f"{info.actual_raw_format.channels}/"
        f"{info.actual_raw_format.bits_per_sample}",
        f"naec_format={info.actual_naec_format.sample_rate_hz}/"
        f"{info.actual_naec_format.channels}/"
        f"{info.actual_naec_format.bits_per_sample}",
    )


def print_capture_status(capture):
    print_capture_info(capture.GetInfo())
    print(
        "[capture status]",
        f"session_id={capture.GetSessionId()}",
        f"cached_state={capture.GetCachedState()}",
    )


def print_devices(devices):
    if not devices:
        print("[devices] none")
        return

    for device in devices:
        print(
            "[device]",
            f"id={device.device_id}",
            f"name={device.display_name}",
            f"direction={device.direction}",
            f"transport={device.transport}",
            f"backend={device.backend_affinity}",
            f"available={device.is_available}",
            f"default={device.is_system_default}",
            f"supports_input={device.supports_input}",
            f"supports_output={device.supports_output}",
            f"provider={device.provider_name}",
            f"native_id={device.native_id}",
            f"metadata={device.metadata_json}",
        )


def format_bt_profiles(profiles):
    if not profiles:
        return "none"
    return ",".join(str(profile) for profile in profiles)


def print_bluetooth_device(device, prefix="[bt device]"):
    print(
        prefix,
        f"address={device.address}",
        f"name={device.name}",
        f"rssi={device.rssi}",
        f"state={device.state}",
        f"major_class={device.major_class}",
        f"paired={device.paired}",
        f"trusted={device.trusted}",
        f"connected={device.connected}",
        f"sink={device.is_audio_sink}",
        f"source={device.is_audio_source}",
        f"hfp={device.is_hfp_capable}",
        f"profiles={format_bt_profiles(device.connected_profiles)}",
        f"pulse_sink={device.linked_pulse_sink_id}",
        f"pulse_source={device.linked_pulse_source_id}",
        f"last_seen_ms={device.last_seen_ms}",
    )


def print_bluetooth_devices(devices):
    if not devices:
        print("[bt devices] none")
        return

    for device in devices:
        print_bluetooth_device(device)


def print_bluetooth_connect_result(result):
    print(
        "[bt connect]",
        f"pulse_sink={result.pulse_sink_id}",
        f"pulse_source={result.pulse_source_id}",
        f"active_profile={result.active_profile}",
        f"pulse_endpoint_ready={result.pulse_endpoint_ready}",
        f"default_sink_applied={result.default_sink_applied}",
        f"default_source_applied={result.default_source_applied}",
        f"default_route_error_code={result.default_route_error_code}",
        f"default_route_error_msg={result.default_route_error_msg}",
    )
    print_bluetooth_device(result.device, prefix="[bt connect device]")


def print_bluetooth_event(event):
    print(
        "[bt event]",
        f"ts={event.timestamp_ms}",
        f"type={event.event_type}",
        f"address={event.address}",
        f"error={event.error_code}",
        f"payload={event.payload_json}",
    )


def format_audio_topic_header(header):
    return (
        f"client_id={header.client_id} "
        f"request_id={header.request_id} "
        f"session_type={header.session_type} "
        f"session_id={header.session_id} "
        f"ts={header.timestamp_ms}"
    )


def print_manager_progress_topic(topic):
    print(
        "[manager progress]",
        format_audio_topic_header(topic.header),
        f"position_bytes={topic.position_bytes}",
        f"duration_bytes={topic.duration_bytes}",
        f"state={topic.state}",
    )


def print_manager_event_topic(topic):
    print(
        "[manager event]",
        format_audio_topic_header(topic.header),
        f"event_code={topic.event_code}",
        f"state={topic.state}",
        f"detail={topic.detail}",
    )


def print_manager_error_topic(topic):
    print(
        "[manager error]",
        format_audio_topic_header(topic.header),
        f"ret_code={topic.ret_code}",
        f"ret_msg={topic.ret_msg}",
        f"category={topic.error_category}",
        f"detail={topic.error_detail}",
    )


def is_current_manager_topic(topic, client_id):
    return topic.header.client_id == client_id


def register_callbacks(player, recorder, capture, manager, capture_counter):
    manager_client_id = manager.GetClientId()
    manager.SetProgressCallback(
        lambda topic: print_manager_progress_topic(topic)
        if is_current_manager_topic(topic, manager_client_id)
        else None
    )
    manager.SetEventCallback(
        lambda topic: print_manager_event_topic(topic)
        if is_current_manager_topic(topic, manager_client_id)
        else None
    )
    manager.SetErrorCallback(
        lambda topic: print_manager_error_topic(topic)
        if is_current_manager_topic(topic, manager_client_id)
        else None
    )
    manager.SetBluetoothEventCallback(print_bluetooth_event)

    player.SetStateCallback(
        lambda state: print(f"[player state] {state}")
    )
    player.SetProgressCallback(
        lambda info: print_player_info(info)
    )
    player.SetCompletionCallback(
        lambda info: print(f"[player complete] played={info.played_bytes}")
    )
    player.SetErrorCallback(
        lambda err: print(
            f"[player error] code={err.ret_code} msg={err.ret_msg} "
            f"category={err.error_category} detail={err.error_detail}"
        )
    )

    recorder.SetStateCallback(
        lambda state: print(f"[recorder state] {state}")
    )
    recorder.SetProgressCallback(
        lambda info: print_recorder_info(info)
    )
    recorder.SetErrorCallback(
        lambda err: print(
            f"[recorder error] code={err.ret_code} msg={err.ret_msg} "
            f"category={err.error_category} detail={err.error_detail}"
        )
    )

    def on_capture_frame(frame):
        capture_counter["frames"] += 1
        if capture_counter["frames"] <= 5 or capture_counter["frames"] % 30 == 0:
            print(
                "[capture frame]",
                f"seq={frame.frame_seq}",
                f"ts={frame.timestamp_ms}",
                f"raw_valid={frame.raw_valid}",
                f"raw_format={frame.raw_format.sample_rate_hz}/"
                f"{frame.raw_format.channels}/"
                f"{frame.raw_format.bits_per_sample}",
                f"raw_samples_per_ch={frame.raw_frame_samples_per_channel}",
                f"raw_samples={len(frame.raw_pcm)}",
                f"naec_valid={frame.naec_valid}",
                f"naec_format={frame.naec_format.sample_rate_hz}/"
                f"{frame.naec_format.channels}/"
                f"{frame.naec_format.bits_per_sample}",
                f"naec_samples_per_ch={frame.naec_frame_samples_per_channel}",
                f"naec_samples={len(frame.naec_pcm)}",
            )

    capture.SetFrameCallback(on_capture_frame)
    capture.SetStateCallback(
        lambda state: print(f"[capture state] {state}")
    )
    capture.SetErrorCallback(
        lambda err: print(
            f"[capture error] code={err.ret_code} msg={err.ret_msg} "
            f"category={err.error_category} detail={err.error_detail}"
        )
    )


def main():
    if len(sys.argv) < 2:
        print(f"Usage: {sys.argv[0]} networkInterface")
        print(f"Example: {sys.argv[0]} eno1")
        sys.exit(-1)

    net_if = sys.argv[1]

    print(f"Initializing ChannelFactory on {net_if}...")
    br.ChannelFactory.Instance().Init(0, net_if)

    manager = br.AudioManager()
    manager.Init()
    print(f"AudioManager initialized, client_id={manager.GetClientId()}")

    player = manager.CreatePlayer()
    recorder = manager.CreateRecorder()
    localizer = manager.CreateLocalizer()
    capture = manager.CreateCaptureStream()

    capture_counter = {"frames": 0}
    register_callbacks(player, recorder, capture, manager, capture_counter)

    print("Audio CLI started.")
    print_help()

    while True:
        try:
            line = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nExit.")
            break

        if not line:
            continue

        parts = line.split()
        cmd = parts[0]
        args = parts[1:]

        try:
            if cmd in ("help", "?"):
                print_help()

            elif cmd == "manager_init":
                manager.Init()
                player = manager.CreatePlayer()
                recorder = manager.CreateRecorder()
                localizer = manager.CreateLocalizer()
                capture = manager.CreateCaptureStream()
                capture_counter["frames"] = 0
                register_callbacks(player, recorder, capture, manager, capture_counter)
                print(f"[OK] audio manager initialized, client_id={manager.GetClientId()}")

            elif cmd == "manager_info":
                print_manager_info(manager)

            elif cmd == "manager_request_id":
                print(f"[OK] request_id={manager.GenerateRequestId()}")

            elif cmd == "manager_shutdown":
                manager.Shutdown()
                print("[OK] audio manager shutdown complete")

            elif cmd == "player_init":
                if len(args) < 2 or len(args) > 3:
                    print("Usage: player_init <pcm|wav|mp3> <path> [priority]")
                    continue

                source_type = AUDIO_SOURCE_MAP.get(args[0].lower())
                if source_type is None:
                    print("source type must be one of: pcm, wav, mp3")
                    continue

                options = br.PlayerInitOptions()
                options.source_type = source_type
                options.source_uri = args[1]
                if len(args) == 3:
                    options.priority = parse_player_priority(args[2])

                player.Init(options)
                print("[OK] player initialized for file playback")

            elif cmd == "player_stream_init":
                if len(args) > 3:
                    print("Usage: player_stream_init [sample_rate] [channels] [bits]")
                    continue

                options = br.PlayerInitOptions()
                options.source_type = br.AudioSourceType.kPcmStream
                options.source_uri = "pcm_stream"
                if len(args) >= 1:
                    options.sample_rate_hz = int(args[0])
                if len(args) >= 2:
                    options.channels = int(args[1])
                if len(args) == 3:
                    options.bits_per_sample = int(args[2])

                player.Init(options)
                print("[OK] player initialized for PCM streaming")

            elif cmd == "player_start":
                player.Start()
                print("[OK] player start sent")

            elif cmd == "player_pause":
                player.Pause()
                print("[OK] player pause sent")

            elif cmd == "player_stop":
                player.Stop()
                print("[OK] player stop sent")

            elif cmd == "player_reset":
                player.Reset()
                print("[OK] player reset sent")

            elif cmd == "player_destroy":
                player.Destroy()
                print("[OK] player destroy sent")

            elif cmd == "player_release":
                player.Release()
                print("[OK] player release sent")

            elif cmd == "player_info":
                print_player_status(player)

            elif cmd == "player_volume":
                if len(args) != 1:
                    print("Usage: player_volume <0.0-1.0>")
                    continue

                player.SetVolume(float(args[0]))
                print("[OK] player volume updated")

            elif cmd == "player_push":
                if len(args) < 1 or len(args) > 3:
                    print("Usage: player_push <pcm_path> [chunk_bytes] [sleep_ms]")
                    continue

                chunk_bytes = int(args[1]) if len(args) >= 2 else 4096
                sleep_ms = int(args[2]) if len(args) == 3 else 20
                with open(args[0], "rb") as f:
                    data = f.read()

                sent = 0
                for offset in range(0, len(data), chunk_bytes):
                    chunk = data[offset : offset + chunk_bytes]
                    player.PushPcmStream(chunk)
                    sent += len(chunk)
                    if sleep_ms > 0:
                        time.sleep(sleep_ms / 1000.0)

                print(f"[OK] pushed {sent} bytes to PCM stream player")

            elif cmd == "rec_init":
                if len(args) < 1 or len(args) > 4:
                    print("Usage: rec_init <output_path> [sample_rate] [channels] [bits]")
                    continue

                options = br.RecorderInitOptions()
                options.output_path = args[0]
                if len(args) >= 2:
                    options.sample_rate_hz = int(args[1])
                if len(args) >= 3:
                    options.channels = int(args[2])
                if len(args) == 4:
                    options.bits_per_sample = int(args[3])

                recorder.Init(options)
                print("[OK] recorder initialized")

            elif cmd == "rec_start":
                recorder.Start()
                print("[OK] recorder start sent")

            elif cmd == "rec_pause":
                recorder.Pause()
                print("[OK] recorder pause sent")

            elif cmd == "rec_stop":
                recorder.Stop()
                print("[OK] recorder stop sent")

            elif cmd == "rec_destroy":
                recorder.Destroy()
                print("[OK] recorder destroy sent")

            elif cmd == "rec_release":
                recorder.Release()
                print("[OK] recorder release sent")

            elif cmd == "rec_info":
                print_recorder_status(recorder)

            elif cmd == "sys_volume":
                if len(args) == 0:
                    print(f"[OK] system volume={manager.GetSystemVolume():.2f}")
                elif len(args) == 1:
                    manager.SetSystemVolume(float(args[0]))
                    print("[OK] system volume updated")
                else:
                    print("Usage: sys_volume [value]")

            elif cmd == "sys_mute":
                if len(args) == 0:
                    print(f"[OK] system mute={manager.GetSystemMute()}")
                elif len(args) == 1:
                    manager.SetSystemMute(parse_bool_token(args[0]))
                    print("[OK] system mute updated")
                else:
                    print("Usage: sys_mute [on|off]")

            elif cmd == "devices":
                if len(args) > 1:
                    print("Usage: devices [inputs|outputs]")
                    continue

                query = br.AudioDeviceQueryType.GET_DEVICES_OUTPUTS
                if len(args) == 1:
                    token = args[0].lower()
                    if token == "inputs":
                        query = br.AudioDeviceQueryType.GET_DEVICES_INPUTS
                    elif token != "outputs":
                        print("Usage: devices [inputs|outputs]")
                        continue

                print_devices(manager.GetDevices(query))

            elif cmd == "player_device":
                if len(args) != 1:
                    print("Usage: player_device <device_id>")
                    continue
                player.SetPreferredDevice(args[0])
                print("[OK] player preferred device updated")

            elif cmd == "rec_device":
                if len(args) != 1:
                    print("Usage: rec_device <device_id>")
                    continue
                recorder.SetPreferredDevice(args[0])
                print("[OK] recorder preferred device updated")

            elif cmd == "cap_device":
                if len(args) != 1:
                    print("Usage: cap_device <device_id>")
                    continue
                capture.SetPreferredDevice(args[0])
                print("[OK] capture preferred device updated")

            elif cmd == "doa":
                angle = localizer.GetDoaAngle()
                print(f"[OK] doa angle={angle} deg")

            elif cmd == "bt_scan":
                if len(args) > 2:
                    print("Usage: bt_scan [timeout_ms] [audio_only]")
                    continue

                options = br.BluetoothScanOptions()
                if len(args) >= 1:
                    options.timeout_ms = int(args[0])
                if len(args) == 2:
                    options.audio_only = parse_bool_token(args[1])

                manager.StartBluetoothScan(options)
                print("[OK] Bluetooth scan started")

            elif cmd == "bt_scan_stop":
                manager.StopBluetoothScan()
                print("[OK] Bluetooth scan stop sent")

            elif cmd == "bt_devices":
                if len(args) > 1:
                    print("Usage: bt_devices [include_unpaired]")
                    continue

                include_unpaired = True
                if len(args) == 1:
                    include_unpaired = parse_bool_token(args[0])

                print_bluetooth_devices(manager.GetBluetoothDevices(include_unpaired))

            elif cmd == "bt_connect":
                if len(args) < 1 or len(args) > 5:
                    print(
                        "Usage: bt_connect <address> [profile] [timeout_ms] "
                        "[auto_pair] [make_default]"
                    )
                    continue

                options = br.BluetoothConnectOptions()
                options.address = args[0]
                if len(args) >= 2:
                    options.preferred_profile = parse_bt_profile(args[1])
                if len(args) >= 3:
                    options.timeout_ms = int(args[2])
                if len(args) >= 4:
                    options.auto_pair = parse_bool_token(args[3])
                if len(args) == 5:
                    options.make_default = parse_bool_token(args[4])

                print_bluetooth_connect_result(
                    manager.ConnectBluetoothDevice(options)
                )

            elif cmd == "bt_disconnect":
                if len(args) != 1:
                    print("Usage: bt_disconnect <address>")
                    continue
                manager.DisconnectBluetoothDevice(args[0])
                print("[OK] Bluetooth disconnect sent")

            elif cmd == "bt_forget":
                if len(args) != 1:
                    print("Usage: bt_forget <address>")
                    continue
                manager.ForgetBluetoothDevice(args[0])
                print("[OK] Bluetooth forget sent")

            elif cmd == "cap_init":
                if len(args) > 4:
                    print("Usage: cap_init [raw|naec|both] [sample_rate] [channels] [bits]")
                    continue

                mode = args[0].lower() if len(args) >= 1 else "raw"
                options = br.AudioCaptureStreamOptions()
                options.enable_raw_pcm = mode in ("raw", "both")
                options.enable_naec_pcm = mode in ("naec", "both")

                if mode not in ("raw", "naec", "both"):
                    print("capture mode must be one of: raw, naec, both")
                    continue

                requested_raw_format = br.PcmFormat()
                # BoosterAEC raw PCM defaults to 16 kHz, 3 channels, 16-bit.
                requested_raw_format.channels = 3
                if len(args) >= 2:
                    requested_raw_format.sample_rate_hz = int(args[1])
                if len(args) >= 3:
                    requested_raw_format.channels = int(args[2])
                if len(args) == 4:
                    requested_raw_format.bits_per_sample = int(args[3])
                options.requested_raw_format = requested_raw_format

                capture_counter["frames"] = 0
                capture.Init(options)
                print("[OK] capture stream initialized")

            elif cmd == "cap_start":
                capture.Start()
                print("[OK] capture start sent")

            elif cmd == "cap_pause":
                capture.Pause()
                print("[OK] capture pause sent")

            elif cmd == "cap_stop":
                capture.Stop()
                print("[OK] capture stop sent")

            elif cmd == "cap_destroy":
                capture.Destroy()
                print("[OK] capture destroy sent")

            elif cmd == "cap_info":
                print_capture_status(capture)

            elif cmd in ("quit", "exit"):
                print("Bye.")
                break

            else:
                print(f"Unknown command: {cmd}")
                print("Type 'help' to show available commands.")

        except Exception as e:
            print(f"[ERROR] Request failed: {e}")


if __name__ == "__main__":
    main()
